const form=document.querySelector('#kitchen-quote-brief');
if(form){let brief=null;const $=s=>document.querySelector(s);const labels={name:'Name',email:'Email',area:'Approximate kitchen area',layout:'Kitchen layout',location:'Project location',style:'Door style',finish:'Cabinet color',timeline:'Renovation timing',lighting:'Preview lighting',product:'Cabinet starting point',notes:'Project notes',marketingConsent:'Marketing email preference'};const colors={'soft-white':'Soft White','warm-ivory':'Warm Ivory','natural-oak':'Natural Oak','charcoal-gray':'Charcoal Gray',unsure:'Help me choose'};const lines=()=>Object.entries(labels).map(([k,label])=>[label,k==='finish'?colors[brief[k]]:k==='marketingConsent'?(brief[k]==='yes'?'Opted in to cabinet offers, products and organization ideas - delivery pending':'Not opted in'):brief[k]||'Not provided']);
form.addEventListener('input',()=>{brief=null;$('#quote-brief-result').hidden=true;});
form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;brief=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,String(v).trim()]));brief.lighting=document.querySelector('#kitchen-rendered-photo:not([hidden])')?document.querySelector('[data-kitchen-light][aria-pressed=true]')?.textContent.trim():'No rendering requested';const summary=$('#quote-brief-summary');summary.replaceChildren();for(const [label,value]of lines()){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;summary.append(dt,dd);}$('#quote-share').href='mailto:info@amberleafhome.us?subject='+encodeURIComponent('My Kabby Home kitchen quote request')+'&body='+encodeURIComponent('Please review my kitchen brief and contact me with the next steps for a personalized cabinet quote.\n\n'+lines().map(([k,v])=>k+': '+v).join('\n')+'\n\nThis is a quote request, not an order.');$('#quote-brief-result').hidden=false;$('#quote-brief-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});
$('#quote-pdf').addEventListener('click',async()=>{if(!brief)return;const button=$('#quote-pdf');button.disabled=true;try{if(!window.jspdf?.jsPDF)throw Error('PDF download could not load. Please reload and try again.');const doc=new window.jspdf.jsPDF();const margin=20;let y=25;const text=(value,size=11)=>{doc.setFontSize(size);for(const line of doc.splitTextToSize(value,170)){if(y>275){doc.addPage();y=25;}doc.text(line,margin,y);y+=size*.5;}y+=4;};doc.setTextColor(40,51,41);text('KABBY HOME',22);text('Your kitchen planning brief',17);text(new Date().toLocaleDateString('en-US'),10);text('Planning record - not a price quote, final design or order confirmation.',10);for(const [label,value]of lines())text(label+': '+value);text('Final pricing follows measurement, specification, accessory-fit and service-scope review.',10);const rendered=$('#kitchen-rendered-photo');if(rendered&&!rendered.hidden&&rendered.src.startsWith('data:image/')){doc.addPage();y=25;text('Your AI kitchen concept',17);text('AI-generated inspiration. Details and finish color may vary from the original or physical samples.',10);const canvas=document.createElement('canvas');canvas.width=rendered.naturalWidth;canvas.height=rendered.naturalHeight;canvas.getContext('2d').drawImage(rendered,0,0);const h=Math.min(200,170*canvas.height/canvas.width),w=h*canvas.width/canvas.height;doc.addImage(canvas.toDataURL('image/jpeg',.9),'JPEG',20,y,w,h);}doc.save('kabbu-home-kitchen-brief.pdf');$('#quote-pdf-status').textContent='PDF downloaded. To send the brief, choose Open email & send request, then send it in your email app.';}catch(e){$('#quote-pdf-status').textContent=e.message;}finally{button.disabled=false;}});
}


if(form){document.querySelectorAll('[data-kitchen-color]').forEach(button=>button.addEventListener('click',()=>{form.elements.finish.value=button.dataset.kitchenColor;}));document.querySelectorAll('[data-kitchen-color],[data-kitchen-light]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#quote-brief-result').hidden=true;}));}

if(form){const params=new URLSearchParams(location.search);for(const key of ['area','layout','style','finish','location']){const value=params.get(key)||(key==='area'?params.get('size'):null),field=form.elements[key];if(value&&field&&(!field.options||[...field.options].some(o=>o.value===value)))field.value=value;}const product=params.get('product');if(product&&/^[a-z-]{1,60}$/.test(product))form.elements.product.value=product;document.querySelector('#kitchen-render')?.addEventListener('click',()=>{const selected=document.querySelector('[data-kitchen-color][aria-pressed=true]');if(selected)form.elements.finish.value=selected.dataset.kitchenColor;});}

// Project and email are collected before rendering; marketing consent stays optional.
if(form){form.addEventListener('click',event=>{if(event.target.closest('#kitchen-render')&&!form.reportValidity()){event.preventDefault();event.stopImmediatePropagation();}},true);}

// Access requests only require a valid email, independently of optional planning fields.
if(form){document.querySelector('#quote-request-access')?.addEventListener('click',()=>{const email=form.elements.email;if(!email.reportValidity())return;const link=document.querySelector('#quote-access-email');link.href='mailto:info@amberleafhome.us?subject='+encodeURIComponent('Kabby Home rendering access request')+'&body='+encodeURIComponent('Please contact me about access to the kitchen rendering feature.\n\nEmail: '+email.value.trim()+'\nMarketing updates: '+(form.elements.marketingConsent.checked?'Yes, opted in':'No'));link.hidden=false;link.focus();});}
